<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Consent\Application\Usecase;

use Civi\Lughauth\Features\Oidc\Consent\Domain\TermsOfUseAcceptance;
use Civi\Lughauth\Features\Oidc\Consent\Domain\Gateway\TermsOfUseConsentGateway;

class TermsOfUseConsentUsecase
{
    public function __construct(
        private readonly TermsOfUseConsentGateway $gateway
    ) {
    }

    /**
     * @param string[] $audiences
     *
     * @return TermsOfUseAcceptance[]
     */
    public function getPendingConsent(string $tenant, string $username, array $audiences): array
    {
        return $this->gateway->getPendingConsent($tenant, $username, $audiences);
    }

    /**
     * @param string[] $audiences
     */
    public function storeAcceptedConsent(string $tenant, string $username, array $audiences, TermsOfUseAcceptance $consent): void
    {
        $this->gateway->storeAcceptedConsent($tenant, $username, $audiences, $consent);
    }
}
